    returnValue += character;

    if (ESCAPES.has(character)) {
      const { groups } = (new RegExp(
        `(?:\\${ANSI_CSI}(?<code>\\d+)m|\\${ANSI_ESCAPE_LINK}(?<uri>.*)${ANSI_ESCAPE_BELL})`,
