Now the cli-printer.js — the redesign with the enableColor flag. Let me rewrite the relevant parts.

Current cli-printer.js structure:
- imports
- `getBarText(percent, maxBarSize)` — module function using chalk.blue / chalk.blue.dim
- `padLeft`, `padRight`
- class CliPrinter with constructor (chalk.level), groupData, _print, print

I'll:
1. Replace `const { default: chalk } = require('chalk');` with `const { styleText } = require('util');`
2. Add helper `function colorText(styles, text, enableColor) { if (!enableColor) return text; return styleText(styles, text, { validateStream: false }); }`
3. Modify `getBarText` to accept `enableColor` param.
4. Constructor: replace `chalk.level = ...` with `this.enableColor = options.enableColor !== false;`
5. Update all chalk calls.

Let me write the edits carefully.

import:
```js
const BasePrinter = require('./printer');
const { default: chalk } = require('chalk');
const { default: prettyMs } = require('pretty-ms');
const { default: figure } = require('figures');
```
→
```js
const BasePrinter = require('./printer');
const { styleText } = require('util');
const { default: prettyMs } = require('pretty-ms');
const { default: figure } = require('figures');

function colorText(styles, text, enableColor) {
    if (!enableColor) return text;
    return styleText(styles, text, { validateStream: false });
}
```

getBarText:
```js
function getBarText(percent, maxBarSize) {
    maxBarSize = Math.max(0, maxBarSize);
    const barNumber = Math.max(Math.ceil((percent / 100) * maxBarSize), 1);
    return (
        chalk.blue(new Array(barNumber + 1).join(figure.square)) +
        chalk.blue.dim(
            new Array(Math.max(0, maxBarSize - barNumber + 1)).join(
                figure.square
            )
        )
    );
}
```
→
```js
function getBarText(percent, maxBarSize, enableColor) {
    maxBarSize = Math.max(0, maxBarSize);
    const barNumber = Math.max(Math.ceil((percent / 100) * maxBarSize), 1);
    return (
        colorText(
            'blue',
            new Array(barNumber + 1).join(figure.square),
            enableColor
        ) +
        colorText(
            ['blue', 'dim'],
            new Array(Math.max(0, maxBarSize - barNumber + 1)).join(
                figure.square
            ),
            enableColor
        )
    );
}
```

constructor:
```js
    constructor(options = {}) {
        super(options);

        chalk.level = options.enableColor !== false ? 3 : 0;
        this.processStart = Date.now();

        this.nameMaxLen = options.nameMaxLen || 30;
    }
```
→
```js
    constructor(options = {}) {
        super(options);

        this.enableColor = options.enableColor !== false;
        this.processStart = Date.now();

        this.nameMaxLen = options.nameMaxLen || 30;
    }
```

_print:
- `chalk.underline(groupedName)` → `colorText('underline', groupedName, this.enableColor)`
- `getBarText(percent, maxBarSize)` → `getBarText(percent, maxBarSize, this.enableColor)`

print:
- `chalk.bgWhite.black(padRight(' Sorted by grouping (aggregate of all thread)', ...))` → `colorText(['bgWhite', 'black'], padRight(' Sorted by grouping (aggregate of all thread)', process.stdout.columns || 80), this.enableColor)`
  - similar for subgroup and pid.
- `chalk.white(\`Process finished in ${chalk.bold(prettyMs(Date.now() - this.processStart))}.\`)` → `colorText('white', \`Process finished in ${colorText('bold', prettyMs(Date.now() - this.processStart), this.enableColor)}.\`, this.enableColor)`

